function backgroundAirships(){return `<div class="air-traffic" aria-hidden="true">${[0,1,2].map(i=>`<div class="airship-route route-${i}"><div class="airship-facing"><div class="airship-bob"><span class="airship-wind"></span><img src="assets/airship-orange-2d.png" alt="" draggable="false"><span class="airship-propeller"></span></div></div></div>`).join('')}</div>`}
const flightPaths=[
  {duration:46,offset:.21,points:[[-.18,.62],[-.02,.22],[.33,.84],[.52,.47],[.72,.08],[.9,.83],[1.18,.30]]},
  {duration:63,offset:.47,points:[[1.18,.25],[.8,.01],[.78,.90],[.49,.42],[.20,.02],[.20,.72],[-.18,.34]]},
  {duration:75,offset:.68,points:[[-.18,.78],[.10,.88],[.70,.15],[.57,.57],[.43,.94],[.24,.35],[.62,.28],[.92,.22],[.93,.65],[1.18,.65]]}
];
let airshipFrame=0;
function flightPoint(points,t){const segments=(points.length-1)/3,s=Math.min(t*segments,segments-.000001),i=Math.floor(s)*3,u=s-Math.floor(s),v=1-u,a=points[i],b=points[i+1],c=points[i+2],d=points[i+3];return {x:v*v*v*a[0]+3*v*v*u*b[0]+3*v*u*u*c[0]+u*u*u*d[0],y:v*v*v*a[1]+3*v*v*u*b[1]+3*v*u*u*c[1]+u*u*u*d[1]}}
function flightLookup(points){const samples=Array.from({length:401},(_,i)=>flightPoint(points,i/400)),lengths=[0];for(let i=1;i<samples.length;i++)lengths.push(lengths[i-1]+Math.hypot(samples[i].x-samples[i-1].x,samples[i].y-samples[i-1].y));return progress=>{const distance=progress*lengths.at(-1);let lo=1,hi=400;while(lo<hi){const mid=(lo+hi)>>1;if(lengths[mid]<distance)lo=mid+1;else hi=mid}const f=(distance-lengths[lo-1])/(lengths[lo]-lengths[lo-1]||1);return flightPoint(points,(lo-1+f)/400)}}
function startCurvedFlights(){cancelAnimationFrame(airshipFrame);const layer=document.querySelector('.air-traffic');if(!layer)return;const ships=[...layer.querySelectorAll('.airship-route')],routes=flightPaths.map(p=>({...p,lookup:flightLookup(p.points)})),reduce=matchMedia('(prefers-reduced-motion: reduce)');let last=0,elapsed=0,lastDraw=0,first=true,oldWidth=0,oldHeight=0;
  function frame(now){if(!layer.isConnected)return;airshipFrame=requestAnimationFrame(frame);const paused=mapMotionPaused||reduce.matches||document.hidden;if(!paused&&last)elapsed+=Math.min(now-last,50)/1000;last=now;const width=layer.clientWidth,height=layer.clientHeight,resize=width!==oldWidth||height!==oldHeight;if(!first&&!resize&&(paused||now-lastDraw<32))return;first=false;lastDraw=now;oldWidth=width;oldHeight=height;ships.forEach((ship,i)=>{const route=routes[i],p=(elapsed/route.duration+route.offset)%1,a=route.lookup(p),b=route.lookup(Math.min(.99999,p+.0005)),dx=(b.x-a.x)*width,dy=(b.y-a.y)*height,facing=dx<0?-1:1;let angle=Math.atan2(dy,dx)*180/Math.PI;if(facing<0)angle+=angle>0?-180:180;angle=Math.max(-38,Math.min(38,angle));const depth=.86+a.y*.23;ship.style.transform=`translate(${(a.x*width).toFixed(2)}px,${(a.y*height).toFixed(2)}px) rotate(${angle.toFixed(2)}deg) scale(${depth.toFixed(3)})`;ship.querySelector('.airship-facing').style.transform=`scaleX(${facing})`;ship.dataset.flightY=a.y.toFixed(4);ship.dataset.flightAngle=angle.toFixed(2)})}
  airshipFrame=requestAnimationFrame(frame);
}
const initializeArchipelago=initWorldAtmosphere;
initWorldAtmosphere=function(){initializeArchipelago();document.querySelector('.living-sky')?.insertAdjacentHTML('beforeend',backgroundAirships());startCurvedFlights()};
